  "Tap the ground to place a cracker, then Fire. Drag to look around.": "പടക്കം വയ്ക്കാൻ നിലത്ത് ടാപ്പ് ചെയ്യൂ, എന്നിട്ട് പൊട്ടിക്കൂ. ചുറ്റും കാണാൻ വലിക്കൂ.",
