  "Thank You": "നന്ദി",
  "Thank you for the lovely wishes! Sending a sky full of light right back to you.": "സ്നേഹം നിറഞ്ഞ ആശംസകൾക്ക് നന്ദി! ഒരു ആകാശം നിറയെ വെളിച്ചം തിരികെ അയയ്ക്കുന്നു.",
  "Thank you,": "നന്ദി,",
  "That code isn’t valid": "ആ കോഡ് ശരിയല്ല",
  "The app reads the names, birthdays and photos of contacts that have a birthday, so it can remind you. They stay on this phone and are never uploaded.": "പിറന്നാൾ ഉള്ള കോൺടാക്റ്റുകളുടെ പേര്, പിറന്നാൾ, ഫോട്ടോ എന്നിവ ഓർമ്മപ്പെടുത്താനായി ആപ്പ് വായിക്കുന്നു. അവ ഈ ഫോണിൽ മാത്രം, ഒരിക്കലും അപ്‌ലോഡ് ചെയ്യില്ല.",
  "The bigger crackers cost gems. Everyday crackers and sparkler writing are always free.": "വലിയ പടക്കങ്ങൾക്ക് ജെംസ് വേണം. സാധാരണ പടക്കങ്ങളും കമ്പിത്തിരി എഴുത്തും എന്നും സൗജന്യം.",
  "The camera is busy. Using the camera view instead.": "ക്യാമറ തിരക്കിലാണ്. പകരം ക്യാമറ വ്യൂ ഉപയോഗിക്കുന്നു.",
  "The headline flies across the sky; the message appears on the card.": "തലക്കെട്ട് ആകാശത്തിലൂടെ പറക്കും; സന്ദേശം കാർഡിൽ കാണും.",
  "The link contains the whole card, so nothing is uploaded. Anyone who opens it sees the show.": "ലിങ്കിൽ തന്നെ കാർഡ് മുഴുവനുണ്ട്, ഒന്നും അപ്‌ലോഡ് ചെയ്യുന്നില്ല. തുറക്കുന്ന ആർക്കും ഷോ കാണാം.",
  "The link contains the whole card, so nothing is uploaded. Host the game online (for example GitHub Pages or Netlify) so friends can open the link.": "ലിങ്കിൽ തന്നെ കാർഡ് മുഴുവനുണ്ട്, ഒന്നും അപ്‌ലോഡ് ചെയ്യുന്നില്ല. സുഹൃത്തുക്കൾക്ക് ലിങ്ക് തുറക്കാൻ ഗെയിം ഓൺലൈനിൽ ഹോസ്റ്റ് ചെയ്യൂ (ഉദാ. GitHub Pages അല്ലെങ്കിൽ Netlify).",
  "The sky is full of light. Burst it first!": "ആകാശം വെളിച്ചം കൊണ്ട് നിറഞ്ഞു. ആദ്യം അത് പൊട്ടിക്കൂ!",
