  "No scores yet. Play today’s Daily Sky to be the first.": "ഇതുവരെ സ്കോറില്ല. ഇന്നത്തെ ഡെയ്‌ലി സ്കൈ കളിച്ച് ഒന്നാമതാകൂ.",
