  "Never get stuck in Diya Path or Rocket Rush. Plus no ads and every cracker free.": "ദീപപ്പാതയിലോ റോക്കറ്റ് റഷിലോ ഒരിക്കലും കുടുങ്ങില്ല. കൂടെ പരസ്യമില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Every chapter of Diya Path and Rocket Rush, open now. Plus no ads and every cracker free.": "ദീപപ്പാതയിലെയും റോക്കറ്റ് റഷിലെയും എല്ലാ അധ്യായവും ഇപ്പോൾ തന്നെ തുറന്നിരിക്കും. കൂടെ പരസ്യമില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Play every past daily puzzle": "പഴയ എല്ലാ ദിവസത്തെ പസിലുകളും കളിക്കൂ",
  "Missed a day? Premium opens every past Daily Diya and Daily Rocket. Plus no ads and every cracker free.": "ഒരു ദിവസം വിട്ടുപോയോ? പഴയ എല്ലാ ഇന്നത്തെ ദീപവും ഇന്നത്തെ റോക്കറ്റും പ്രീമിയം തുറക്കും. കൂടെ പരസ്യമില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Every cracker free with Premium": "പ്രീമിയത്തിൽ എല്ലാ പടക്കവും സൗജന്യം",
  "Finales, cakes and rocket combos with no gems, plus no ads and unlimited puzzle hints.": "ഫിനാലെ, കേക്ക്, റോക്കറ്റ് കോംബോ ജെംസില്ലാതെ, കൂടെ പരസ്യമില്ല, പരിധിയില്ലാത്ത പസിൽ സൂചനകൾ.",
  "No banners or videos, every cracker free, and unlimited puzzle hints.": "ബാനറുമില്ല, വീഡിയോയുമില്ല, എല്ലാ പടക്കവും സൗജന്യം, പരിധിയില്ലാത്ത പസിൽ സൂചനകൾ.",
  "No ads. Every cracker. Every level.": "പരസ്യമില്ല. എല്ലാ പടക്കവും. എല്ലാ ലെവലും.",
  "One payment of {0}, charged to your {1} when you confirm. Not a subscription: nothing renews, and Premium is yours to keep. Restore it on a new phone with the same account.": "{0} ഒറ്റത്തവണ പേയ്‌മെന്റ്, നിങ്ങൾ ഉറപ്പിക്കുമ്പോൾ നിങ്ങളുടെ {1} ൽ നിന്ന് ഈടാക്കും. ഇതൊരു സബ്‌സ്‌ക്രിപ്‌ഷനല്ല: ഒന്നും പുതുക്കില്ല, പ്രീമിയം എന്നും നിങ്ങളുടേത്. അതേ അക്കൗണ്ടുള്ള പുതിയ ഫോണിൽ വീണ്ടെടുക്കാം.",
