  "Golden diyas and royal boards": "സ്വർണ ദീപങ്ങളും രാജകീയ ബോർഡുകളും",
  "Premium dresses Diya Path in gold, with palace, river ghat and temple boards. Plus no ads and every cracker free.": "പ്രീമിയം ദീപപ്പാതയെ സ്വർണത്താൽ അലങ്കരിക്കും, കൊട്ടാരം, കടവ്, ക്ഷേത്രം ബോർഡുകളോടെ. കൂടെ പരസ്യമില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Golden diyas & royal boards": "സ്വർണ ദീപങ്ങളും രാജകീയ ബോർഡുകളും",
  "All styles": "എല്ലാ സ്റ്റൈലുകളും",
  "India’s landmarks in 3D": "ഇന്ത്യയുടെ സ്മാരകങ്ങൾ 3D-യിൽ",
  "Walk the forecourt of all 15 landmarks in 3D and look around as the fireworks burst. Plus no ads and every cracker free.": "എല്ലാ 15 സ്മാരകങ്ങളുടെയും മുറ്റത്ത് 3D-യിൽ നടക്കൂ, പടക്കം പൊട്ടുമ്പോൾ ചുറ്റും നോക്കൂ. കൂടെ പരസ്യമില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Fireworks in your room with AR": "AR-ൽ നിങ്ങളുടെ മുറിയിൽ വെടിക്കെട്ട്",
  "Point your camera and light crackers on your own floor and sky. Plus no ads and every cracker free.": "ക്യാമറ തിരിക്കൂ, സ്വന്തം നിലത്തും ആകാശത്തും പടക്കം കത്തിക്കൂ. കൂടാതെ പരസ്യമില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Sacred backgrounds for Diya Path": "ദീപപ്പാതയ്ക്ക് പുണ്യ പശ്ചാത്തലങ്ങൾ",
  "Play before Lakshmi, Ganesha, Balaji, the Golden Temple and more. Plus no ads and every cracker free.": "ലക്ഷ്മി, ഗണപതി, ബാലാജി, സുവർണ്ണ ക്ഷേത്രം എന്നിവയ്ക്ക് മുന്നിൽ കളിക്കൂ. കൂടാതെ പരസ്യമില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Couldn’t load the plans from the store. Check you’re signed in and online, then try again.": "സ്റ്റോറിൽ നിന്ന് പ്ലാനുകൾ ലോഡ് ചെയ്യാനായില്ല. സൈൻ ഇൻ ചെയ്തിട്ടുണ്ടോ, ഓൺലൈനാണോ എന്ന് നോക്കി വീണ്ടും ശ്രമിക്കൂ.",
  "See what Premium adds": "Premium എന്ത് ചേർക്കുന്നു എന്ന് കാണൂ",
  "Sacred backgrounds": "പുണ്യ പശ്ചാത്തലങ്ങൾ",
