  "Free for everyone and included with every plan.": "എല്ലാവർക്കും സൗജന്യം, എല്ലാ പ്ലാനിലും ഉൾപ്പെടും.",
  "AR pictures are illustrations; the look on your phone depends on your camera and room. AR crackers on your real floor need a phone that supports Google Play Services for AR.": "AR ചിത്രങ്ങൾ ഉദാഹരണങ്ങൾ മാത്രം; ഫോണിലെ കാഴ്ച ക്യാമറയെയും മുറിയെയും ആശ്രയിക്കും. യഥാർത്ഥ നിലത്ത് AR പടക്കങ്ങൾക്ക് Google Play Services for AR പിന്തുണയ്ക്കുന്ന ഫോൺ വേണം.",
