  "May Lord Ganesha remove every obstacle and fill your life with joy. Happy Ganesh Chaturthi!": "ഗണപതി ഭഗവാൻ എല്ലാ വിഘ്നങ്ങളും നീക്കി ജീവിതം സന്തോഷം കൊണ്ട് നിറയ്ക്കട്ടെ. വിനായക ചതുർത്ഥി ആശംസകൾ!",
