  "A thousand crackers on a bamboo pole": "മുളങ്കമ്പിൽ ആയിരം പടക്കങ്ങൾ",
  "Every cracker free": "എല്ലാ പടക്കവും സൗജന്യം",
  "Finales, saravedi and seven shots, every night": "ഫിനാലെ, സരവെടി, സെവൻ ഷോട്ട്, എല്ലാ രാത്രിയും",
  "Five Premium crackers": "അഞ്ച് പ്രീമിയം പടക്കങ്ങൾ",
  "The thousand-cracker Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi. One free try each.": "ആയിരം പടക്കങ്ങളുടെ ആയിരം മാലപ്പടക്കം, സരവെടി, സെവൻ ഷോട്ട്, ഡബിൾ ഷോട്ട്, ലക്ഷ്മി പടക്കം. ഓരോന്നിനും ഒരു സൗജന്യ ശ്രമം.",
  "Grand finales, wedding cakes, sutli bombs and more. One of each costs {0} without Premium.": "ഗ്രാൻഡ് ഫിനാലെ, വെഡ്ഡിംഗ് കേക്ക്, ചണബോംബ് എന്നിങ്ങനെ പലതും. പ്രീമിയം ഇല്ലാതെ ഓരോന്നും ഒരിക്കൽ കത്തിക്കാൻ {0} വേണം.",
  "A grand finale and a wedding cake every evening for a month: {0} (about {1} at gem-pack prices). With Premium they’re free, with everything above.": "ഒരു മാസം എല്ലാ വൈകുന്നേരവും ഒരു ഗ്രാൻഡ് ഫിനാലെയും ഒരു വെഡ്ഡിംഗ് കേക്കും: {0} (ജെം പായ്ക്ക് വിലയിൽ ഏകദേശം {1}). പ്രീമിയത്തിൽ ഇവ സൗജന്യം, മുകളിലുള്ള എല്ലാത്തിനുമൊപ്പം.",
  "A grand finale and a wedding cake every evening for a month: {0}. With Premium they’re free, with everything above.": "ഒരു മാസം എല്ലാ വൈകുന്നേരവും ഒരു ഗ്രാൻഡ് ഫിനാലെയും ഒരു വെഡ്ഡിംഗ് കേക്കും: {0}. പ്രീമിയത്തിൽ ഇവ സൗജന്യം, മുകളിലുള്ള എല്ലാത്തിനുമൊപ്പം.",
  "Light the {0} with Premium": "പ്രീമിയത്തിൽ {0} കത്തിക്കൂ",
  "Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi, lit with your sparkler. Plus no ads and every cracker free.": "ആയിരം മാലപ്പടക്കം, സരവെടി, സെവൻ ഷോട്ട്, ഡബിൾ ഷോട്ട്, ലക്ഷ്മി പടക്കം, നിങ്ങളുടെ കമ്പിത്തിരി കൊണ്ട് കത്തിക്കൂ. കൂടെ പരസ്യങ്ങളില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Hazaar ladi, saravedi, seven shot and more": "ആയിരം മാലപ്പടക്കം, സരവെടി, സെവൻ ഷോട്ട് എന്നിവയും മറ്റും",
  "1 free try each": "ഓരോന്നിനും 1 സൗജന്യ ശ്രമം",
  "Big crackers: finale, cake, sutli bomb…": "വലിയ പടക്കങ്ങൾ: ഫിനാലെ, കേക്ക്, ചണബോംബ്…",
  "Three Premium sky shells": "മൂന്ന് പ്രീമിയം ആകാശ ഷെല്ലുകൾ",
  "Peacock, butterfly and magic wand bursts. One free try each.": "മയിൽ, പൂമ്പാറ്റ, മാന്ത്രികവടി പൊട്ടലുകൾ. ഓരോന്നിനും ഒരു സൗജന്യ ശ്രമം.",
  "Peacock, butterfly and magic wand shells, lit with your sparkler. Plus no ads and every cracker free.": "മയിൽ, പൂമ്പാറ്റ, മാന്ത്രികവടി ഷെല്ലുകൾ, നിങ്ങളുടെ കമ്പിത്തിരി കൊണ്ട് കത്തിക്കൂ. കൂടെ പരസ്യങ്ങളില്ല, എല്ലാ പടക്കവും സൗജന്യം.",
  "Peacock, butterfly and magic wand shells": "മയിൽ, പൂമ്പാറ്റ, മാന്ത്രികവടി ഷെല്ലുകൾ",
