  "Free skies, bright hearts. Happy Independence Day! Jai Hind!": "സ്വതന്ത്ര ആകാശം, തിളങ്ങുന്ന ഹൃദയങ്ങൾ. ജയ് ഹിന്ദ്!",
  "Happy Independence Day! You taught me to love this country and stand tall.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! ഈ നാടിനെ സ്നേഹിക്കാനും തലയുയർത്തി നിൽക്കാനും പഠിപ്പിച്ചു.",
  "Happy Independence Day! Thank you for the stories of the freedom you lived through.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! നിങ്ങൾ കണ്ട സ്വാതന്ത്ര്യത്തിന്റെ കഥകൾക്ക് നന്ദി.",
  "Happy Independence Day! Free to dream, and dreaming with you.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! സ്വപ്നം കാണാനുള്ള സ്വാതന്ത്ര്യം, നിന്നോടൊപ്പം സ്വപ്നം.",
  "Happy Independence Day! May you grow up proud, free and kind.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! അഭിമാനത്തോടെ, സ്വതന്ത്രമായി, ദയയോടെ വളരട്ടെ.",
  "Happy Independence Day! Kites, flags and you: the best kind of holiday.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! പട്ടങ്ങൾ, കൊടികൾ, നീ: മികച്ച അവധി.",
  "Happy Independence Day to our whole family! Jai Hind!": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! ഞങ്ങളുടെ മുഴുവൻ കുടുംബത്തിനും! ജയ് ഹിന്ദ്!",
  "Happy Independence Day, friend! Here’s to freedom, and to us.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! സുഹൃത്തേ, സ്വാതന്ത്ര്യത്തിനും നമുക്കും.",
  "Happy Independence Day! Thank you for teaching us to think freely.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! സ്വതന്ത്രമായി ചിന്തിക്കാൻ പഠിപ്പിച്ചതിന് നന്ദി.",
  "Happy Independence Day to the team! Proud to build with you.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! മുഴുവൻ ടീമിനും! നിങ്ങളോടൊപ്പം പണിയാൻ അഭിമാനം.",
  "Happy Independence Day! Free skies, bright hearts, and you in mine.": "സ്വാതന്ത്ര്യ ദിനാശംസകൾ! സ്വതന്ത്ര ആകാശം, തിളങ്ങുന്ന ഹൃദയം, അതിൽ നീ.",
